'use strict';

// MODULES //

var serialize = require( '@stdlib/ndarray/base/serialize-meta-data' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Computes a one-sample Z-test for a one-dimensional single-precision floating-point ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional output ndarray containing a results object.
*     -   a zero-dimensional ndarray specifying the alternative hypothesis.
*     -   a zero-dimensional ndarray specifying the significance level.
*     -   a zero-dimensional ndarray specifying the mean under the null hypothesis.
*     -   a zero-dimensional ndarray specifying the known standard deviation.
*
* -   The output ndarray's underlying results object is written to directly via a `DataView`, as the object's memory layout does not correspond to any ndarray-supported data type.
*
* @private
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {ndarrayLike} output ndarray
*/
function sztest( arrays ) {
	var sigma = arrays[ 5 ];
	var alpha = arrays[ 3 ];
	var alt = arrays[ 2 ];
	var mu = arrays[ 4 ];
	var x = arrays[ 0 ];
	var y = arrays[ 1 ];

	addon( getData( x ), serialize( x ), getData( alt ), serialize( alt ), getData( alpha ), serialize( alpha ), getData( mu ), serialize( mu ), getData( sigma ), serialize( sigma ), y.get().toDataView() ); // eslint-disable-line max-len

	return y;
}


// EXPORTS //

module.exports = sztest;
